import{_ as a,o as r,c as s,a3 as e}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"03 · 检索与重排：怎么找到最相关的几块","description":"","frontmatter":{},"headers":[],"relativePath":"ai/rag/03.md","filePath":"ai/rag/03.md"}'),o={name:"ai/rag/03.md"};function l(d,t,i,n,h,c){return r(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="_03-·-检索与重排-怎么找到最相关的几块" tabindex="-1">03 · 检索与重排：怎么找到最相关的几块 <a class="header-anchor" href="#_03-·-检索与重排-怎么找到最相关的几块" aria-label="Permalink to &quot;03 · 检索与重排：怎么找到最相关的几块&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>向量检索为什么要用「近似」最近邻，HNSW 大概怎么工作。</li><li>关键词检索（BM25）和向量检索各自擅长什么，怎么用 RRF 合并成混合检索。</li><li>重排（Rerank）为什么能提升效果：先粗筛、再精排。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>库建好了（上一篇）。这一篇讲<strong>在线阶段最关键的一步</strong>：从几万、几百万块里找出最相关的几块。</p><p>本篇讲 4 个点：① 向量检索怎么做到快 → ② 关键词检索补什么短板 → ③ 混合检索怎么合并 → ④ 重排为什么能更准。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>检索 = 先用便宜的方法快速捞一批候选（召回），再用贵但准的方法给候选排个序（重排），最后取前几名交给大模型。</strong></p><h2 id="生活类比-公司招聘" tabindex="-1">生活类比：公司招聘 <a class="header-anchor" href="#生活类比-公司招聘" aria-label="Permalink to &quot;生活类比：公司招聘&quot;">​</a></h2><ul><li><strong>简历初筛（召回）</strong>：HR 一天看上千份，用关键词、学历快速筛出 50 份。快，但粗。</li><li><strong>面试（重排）</strong>：对这 50 人逐个深聊，挑出最合适的 3 个。准，但慢，没法对 1000 人都面试。</li><li>两步配合：<strong>又快又准</strong>。</li></ul><h2 id="一步步看" tabindex="-1">一步步看 <a class="header-anchor" href="#一步步看" aria-label="Permalink to &quot;一步步看&quot;">​</a></h2><h3 id="_1-向量检索-近似最近邻" tabindex="-1">1. 向量检索：近似最近邻 <a class="header-anchor" href="#_1-向量检索-近似最近邻" aria-label="Permalink to &quot;1. 向量检索：近似最近邻&quot;">​</a></h3><p>最笨的办法：问题向量和库里<strong>每一块</strong>都算一次相似度，再排序。100 万块就要算 100 万次，太慢。</p><p><strong>ANN（近似最近邻）</strong> 的思路：牺牲一点点准确率，换取速度。常见算法 <strong>HNSW</strong> 可以理解成「<strong>分层的交通网</strong>」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顶层：只有几个大城市，高铁直达        → 先快速跳到大致区域</span></span>
<span class="line"><span>中层：城市更多，有普通火车            → 逐步缩小范围</span></span>
<span class="line"><span>底层：所有小镇都在，走乡间小路        → 在附近精确找最近的</span></span></code></pre></div><p>查询时从顶层开始，每层都往「离目标更近」的点走，越往下越精细。不用遍历全部，就能找到<strong>几乎</strong>是最近的那些块。</p><h3 id="_2-关键词检索-bm25" tabindex="-1">2. 关键词检索：BM25 <a class="header-anchor" href="#_2-关键词检索-bm25" aria-label="Permalink to &quot;2. 关键词检索：BM25&quot;">​</a></h3><p>向量检索擅长「意思相近」，但有个短板：<strong>专有名词、编号、型号</strong>。</p><p>问「错误码 E1043 怎么处理」，向量检索可能找回一堆「讲错误处理的通用段落」，偏偏漏掉写着 <code>E1043</code> 的那一块。</p><p><strong>BM25</strong> 是经典的关键词打分方法，大白话就三条：</p><ul><li>问题里的词在这块里<strong>出现越多</strong>，分越高（但增长有上限，不会无限加分）；</li><li>这个词在全库<strong>越稀有</strong>（比如 E1043），出现一次越值钱；「的」「是」到处都有，几乎不加分；</li><li>块越长，分数会被适当压低，防止长块靠堆字数取胜。</li></ul><h3 id="_3-混合检索-用-rrf-合并两份名单" tabindex="-1">3. 混合检索：用 RRF 合并两份名单 <a class="header-anchor" href="#_3-混合检索-用-rrf-合并两份名单" aria-label="Permalink to &quot;3. 混合检索：用 RRF 合并两份名单&quot;">​</a></h3><p>两种检索各给出一份排名，怎么合并？分数的尺度不同（余弦在 −1 到 1 之间，BM25 可能是 12.7），没法直接相加。</p><p><strong>RRF（倒数排名融合）</strong>：不看分数，只看<strong>名次</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RRF 分 = Σ 1 / (k + 名次)          常用 k = 60</span></span></code></pre></div><p>例子（k = 60）：</p><table tabindex="0"><thead><tr><th>文档块</th><th>向量检索名次</th><th>BM25 名次</th><th>RRF 分</th></tr></thead><tbody><tr><td>A</td><td>1</td><td>3</td><td>1/61 + 1/63 ≈ 0.0323</td></tr><tr><td>B</td><td>2</td><td>1</td><td>1/62 + 1/61 ≈ 0.0325</td></tr><tr><td>C</td><td>3</td><td>没进榜</td><td>1/63 ≈ 0.0159</td></tr></tbody></table><p>B 在两边都靠前，排第一；C 只在一边出现，排最后。<strong>两边都认可的，才靠前。</strong></p><h3 id="_4-重排-rerank" tabindex="-1">4. 重排：Rerank <a class="header-anchor" href="#_4-重排-rerank" aria-label="Permalink to &quot;4. 重排：Rerank&quot;">​</a></h3><p>召回阶段（向量 + BM25）快速拿到比如 <strong>30 块</strong>，再用<strong>重排模型</strong>逐块精细打分，取前 <strong>5 块</strong>给大模型。</p><p>两种模型的区别是重点：</p><table tabindex="0"><thead><tr><th></th><th>Embedding 模型（召回用）</th><th>重排模型（精排用）</th></tr></thead><tbody><tr><td>怎么看</td><td>问题、文档<strong>分别</strong>变成向量，再比较</td><td>把「问题 + 文档」<strong>放在一起</strong>读，直接打相关分</td></tr><tr><td>类比</td><td>看两人简历照片，判断像不像</td><td>让两人面对面聊一次</td></tr><tr><td>速度</td><td>快，文档向量可以提前算好</td><td>慢，每对都要现场算</td></tr><tr><td>准确度</td><td>一般</td><td>高</td></tr></tbody></table><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么用近似最近邻-而不是精确找" tabindex="-1">为什么用近似最近邻，而不是精确找？ <a class="header-anchor" href="#为什么用近似最近邻-而不是精确找" aria-label="Permalink to &quot;为什么用近似最近邻，而不是精确找？&quot;">​</a></h3><ul><li><strong>问题</strong>：精确比较要和每一块都算一次，数据量一大就太慢。</li><li><strong>方案</strong>：用 HNSW 这类索引，分层导航，只访问一小部分点。</li><li><strong>好处</strong>：查询从「全部扫一遍」变成「跳几步」，毫秒级返回，准确率损失很小。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>精确检索要和所有向量比一遍，数据量大时太慢；ANN 用索引结构只访问少量候选，以极小的精度损失换来数量级的速度提升。</p></div><h3 id="为什么要混合检索" tabindex="-1">为什么要混合检索？ <a class="header-anchor" href="#为什么要混合检索" aria-label="Permalink to &quot;为什么要混合检索？&quot;">​</a></h3><ul><li><strong>问题</strong>：向量检索不擅长专有名词、编号、精确术语；关键词检索不认同义词。</li><li><strong>方案</strong>：两路一起检索，再用 RRF 按名次合并。</li><li><strong>好处</strong>：语义匹配和精确匹配互补，召回更全。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>向量检索懂语义但对专有名词不敏感，BM25 精确匹配关键词但不懂同义词，混合检索取长补短；用 RRF 按名次融合，避免两种分数尺度不同的问题。</p></div><h3 id="为什么要两阶段-召回-重排-不直接用重排模型" tabindex="-1">为什么要两阶段（召回 + 重排），不直接用重排模型？ <a class="header-anchor" href="#为什么要两阶段-召回-重排-不直接用重排模型" aria-label="Permalink to &quot;为什么要两阶段（召回 + 重排），不直接用重排模型？&quot;">​</a></h3><ul><li><strong>问题</strong>：重排模型准，但要把问题和每一块拼在一起算一遍，对 100 万块做不到。</li><li><strong>方案</strong>：先用快的方法召回几十块，再只对这几十块重排。</li><li><strong>好处</strong>：兼顾速度和准确率。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>重排模型准但慢，没法对全库使用；先用向量和关键词快速召回几十条，再对这一小批精排，兼顾速度和效果。</p></div><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Retrieval</td><td>retrieve 取回 + -al</td><td>检索</td></tr><tr><td>Recall</td><td>re 再 + call 叫</td><td>召回：先捞出候选；也指「该找到的找到了多少」</td></tr><tr><td>ANN</td><td>Approximate 近似的 + Nearest 最近的 + Neighbor 邻居</td><td>近似最近邻搜索</td></tr><tr><td>HNSW</td><td>Hierarchical 分层的 + Navigable 可导航的 + Small World 小世界</td><td>分层导航的图索引，常用的 ANN 算法</td></tr><tr><td>BM25</td><td>Best Matching 最佳匹配 + 第 25 版公式</td><td>经典的关键词相关性打分方法</td></tr><tr><td>Hybrid Search</td><td>hybrid 混合的 + search 搜索</td><td>向量 + 关键词混合检索</td></tr><tr><td>RRF</td><td>Reciprocal 倒数的 + Rank 排名 + Fusion 融合</td><td>按名次倒数合并多路结果</td></tr><tr><td>Rerank</td><td>re 重新 + rank 排序</td><td>重排：对候选再精细排序</td></tr><tr><td>Bi-encoder / Cross-encoder</td><td>bi 双 / cross 交叉 + encoder 编码器</td><td>分开编码再比较 / 拼在一起编码直接打分</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：向量检索和关键词检索各自的优缺点？</strong></p><blockquote><p>向量检索能匹配语义、同义词，但对专有名词、编号、精确短语不敏感，可解释性差；BM25 精确匹配关键词、对罕见词敏感、可解释，但不懂同义词。实际常用混合检索。</p></blockquote><p><strong>Q：什么是 Rerank？为什么能提升效果？</strong></p><blockquote><p>在召回之后，用 cross-encoder 把问题和每个候选拼在一起打相关性分数并重新排序。它能让问题和文档的词直接交互，比 bi-encoder 分开编码再比较更准；因为慢，只用于召回后的几十条候选。</p></blockquote><p><strong>Q：RRF 是怎么融合的？为什么不直接把分数相加？</strong></p><blockquote><p>每路结果按名次计算 1/(k + rank)，累加作为最终分数，k 常取 60。不同检索的分数尺度和分布不一样，直接相加没有意义；RRF 只用名次，简单稳健。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>召回（Recall）有两个意思</strong>：一是流程上的「召回阶段」；二是评估指标「召回率」。看上下文区分。</li><li><strong>近似 ≠ 不准</strong>：HNSW 的结果在绝大多数情况下和精确结果一样或非常接近，参数可以在速度和精度之间调。</li><li><strong>重排不能找回没召回的块</strong>：召回阶段漏掉的，重排也救不回来。所以召回要「宁多勿漏」，重排负责「去粗取精」。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/03">Embedding</a>：向量检索比较的就是余弦相似度。</li><li><strong>← 来自</strong> <a href="/study-hub/ai/rag/02">切块与入库</a>：元数据可以在检索时做过滤。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/04">评估与常见坑</a>：召回率、命中率就是用来衡量这一步的。</li><li><strong>类比</strong> <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>：数据库用 B+ 树加速精确查找，向量库用 HNSW 加速相似查找，都是「先建索引，查时少走路」。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：用「招聘」类比，说清召回和重排的分工。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>召回像 HR 简历初筛：用快速、粗略的方法从上千份里挑出几十份；重排像面试：对这几十个人逐个深入评估，选出最好的几个。先快后准，兼顾效率和效果。</p></details><p><strong>Q2：问「错误码 E1043 怎么处理」，只用向量检索可能出什么问题？怎么解决？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>向量检索对编号、专有名词不敏感，可能找回一堆讲「错误处理」的通用段落，漏掉真正写着 E1043 的那块。解决：加上 BM25 关键词检索做<strong>混合检索</strong>，再用 RRF 合并结果。</p></details><p><strong>Q3：为什么重排模型比 Embedding 检索准，却不能直接拿来检索全库？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>重排模型把问题和文档<strong>拼在一起</strong>读，词与词之间能直接交互，所以更准；但每对都要现场算，全库几百万块算不过来。所以只对召回后的几十条用它。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用「分层交通网」类比，说清 HNSW 为什么快</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出 BM25 打分的三条大白话规则</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能手算一个 RRF 的例子，并解释为什么不直接把分数相加</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能对比 bi-encoder（Embedding）和 cross-encoder（重排）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能讲清「两阶段检索」的设计理由（问题 → 方案 → 好处）</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>RAG 搭好了，怎么判断它好不好？答错了从哪查起？→ <a href="/study-hub/ai/rag/04">评估与常见坑</a></li></ul>`,65)])])}const u=a(o,[["render",l]]);export{g as __pageData,u as default};
